      "claim": "The 'monitorability tax' creates a direct, quantifiable degradation in model accuracy and reasoning capability.",
      "targets": []
    },
    {
      "claim": "Empirical reliability in high-stakes environments is a more objective safety metric than post-hoc narratives designed to satisfy human intuition.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Intelligence and interpretability are inherently inversely correlated in high-performance neural architectures.",
      "if_wrong": "If high-performance models can be made fully interpretable without a performance penalty, the 'monitorability tax' argument collapses, and safetyist oversight becomes a net positive."
