    {
      "symbol": "⚖️",
      "tooltip": "Institutional accountability is like a balance scale, it weighs the value of statistical precision against the necessity of individual rights to ensure neither is discarded for the sake of the other."
    },
    {
      "symbol": "🔍",
      "tooltip": "Mechanistic interpretability is like a magnifying glass, it reveals the hidden logic within complex systems to prevent errors that aggregate statistics would otherwise obscure."
    }
  ],
  "claim_sketches": [
    {
      "claim": "Institutional legitimacy relies on the ability to audit the reasoning behind life-altering decisions.",
      "targets": ["AN-31"]
    },
    {
      "claim": "Accelerationist assumes that aggregate performance metrics provide a sufficient mandate for deployment while ignoring the fundamental requirement of procedural fairness.",
      "targets": ["AN-31"]
    },
    {
      "claim": "A 15 percent improvement in diagnosis is meaningless to the individual patient if that diagnosis is the result of an opaque heuristic that cannot be verified or corrected.",
      "targets": ["AN-28"]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "The ability to contest a decision requires understanding the specific internal reasoning path that led to that decision.",
      "if_wrong": "If contestation can be achieved solely through outcome-based adversarial testing, the requirement for internal interpretability loses its primary procedural justification."
    },
    {
      "assumption": "Opaque systems carry systemic risks that are not fully captured by aggregate error rates.",
      "if_wrong": "If opaque systems are empirically proven to be as safe as interpretable ones, the 'monitorability tax' becomes a purely ideological cost."
